// n8n Code node — "Build Recipients"
// Normalises the People-tab "Missing Bank Info · Notify" payload into ONE item
// per recipient, each carrying a ready-to-send red-alarm HTML email.
//
// Accepted payload shapes (n8n may nest the POST body under `.body`):
//   { "to": "a@x.com", "name": "Ana" }
//   { "recipient_email": "a@x.com", "recipient_name": "Ana" }
//   { "emails": ["a@x.com", "b@x.com"] }                       // request-bank-info route
//   { "recipients": [ { "email": "a@x.com", "name": "Ana" } ] } // request-bank-info route
//
// The subject, body and destination URL are FIXED and code-owned here — callers
// can only choose WHO is emailed, never what the email says or where it links.
// (This deliberately removes the earlier html/link/subject overrides so the
// endpoint can't be turned into an arbitrary-content mailer.)

// --- OPTIONAL shared-secret gate (recommended for this bank-detail email) ---
// Leave '' to accept any caller (matches the other Simple HRIS webhooks). To lock
// it down: put a long random string here AND set the same value in the HRIS env
// var N8N_BANK_INFO_NOTIFY_SECRET, so the server sends it as the 'x-webhook-secret'
// header. When set, any request without a matching secret is rejected.
const REQUIRED_SECRET = '';

const UPDATE_LINK = 'https://bank-payout-update.vercel.app/update-bank-info';
const LOGO = 'https://simple-hris.vercel.app/simple-logo.png';
const SUPPORT_EMAIL = 'payroll@simple.biz';
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
// Ceiling aligned with Gmail's ~2,000/day send limit. The workflow sends these
// in throttled batches (SplitInBatches + Wait), so large lists don't burst.
const MAX = 2000;

const root = (items[0] && items[0].json) || {};
const body = (root && typeof root.body === 'object' && root.body) ? root.body : root;
const headers = (root && typeof root.headers === 'object' && root.headers) ? root.headers : {};

const providedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || body.secret || '';
if (REQUIRED_SECRET && providedSecret !== REQUIRED_SECRET) {
  throw new Error('Unauthorized: missing or invalid webhook secret.');
}

function esc(v) {
  if (v == null) return '';
  return String(v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}
function firstName(name) {
  const n = (name == null ? '' : String(name)).trim();
  if (!n) return '';
  return n.split(/\s+/)[0];
}

// --- collect recipients from any supported shape ---
const collected = [];
if (Array.isArray(body.recipients)) {
  for (const r of body.recipients) {
    if (!r) continue;
    collected.push({
      email: r.email || r.work_email || r.to || r.recipient_email,
      name: r.name || r.recipient_name || '',
    });
  }
}
if (Array.isArray(body.emails)) {
  for (const e of body.emails) collected.push({ email: e, name: '' });
}
if (body.recipient_email) collected.push({ email: body.recipient_email, name: body.recipient_name || body.name || '' });
if (body.to) collected.push({ email: body.to, name: body.name || body.recipient_name || '' });

// normalise + validate + dedupe (keep the first non-empty name seen per address)
const seen = new Map();
for (const c of collected) {
  const email = (c.email == null ? '' : String(c.email)).trim().toLowerCase();
  if (!email || !EMAIL_RE.test(email)) continue;
  const name = (c.name == null ? '' : String(c.name)).trim();
  if (!seen.has(email)) seen.set(email, name);
  else if (!seen.get(email) && name) seen.set(email, name);
}
if (seen.size === 0) {
  throw new Error('No valid recipient email(s) in payload. Send { to } / { recipient_email } / { emails: [] } / { recipients: [] }.');
}
if (seen.size > MAX) {
  throw new Error('Too many recipients (' + seen.size + '; max ' + MAX + ' — Gmail daily limit). Split into smaller runs.');
}

// Bulletproof CTA button — VML roundrect for Outlook (Word engine ignores padding
// on inline <a>), a padded inline-block <a> for every other client.
function ctaButton() {
  return '' +
    '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:4px 0 6px"><tr><td>' +
      '<!--[if mso]><v:roundrect xmlns:v="urn:schemas-microsoft-com:vml" xmlns:w="urn:schemas-microsoft-com:office:word" href="' + UPDATE_LINK + '" style="height:48px;v-text-anchor:middle;width:260px;" arcsize="21%" strokecolor="#dc2626" fillcolor="#dc2626"><w:anchorlock/><center style="color:#ffffff;font-family:Arial,sans-serif;font-size:15px;font-weight:bold;">Update my bank details</center></v:roundrect><![endif]-->' +
      '<!--[if !mso]><!-- --><a href="' + UPDATE_LINK + '" style="display:inline-block;background:#dc2626;color:#ffffff;font-size:15px;font-weight:bold;text-decoration:none;padding:14px 28px;border-radius:10px">Update my bank details &rarr;</a><!--<![endif]-->' +
    '</td></tr></table>';
}

function renderHtml(name) {
  const fn = esc(firstName(name));
  const greeting = fn ? ('Hi ' + fn + ',') : 'Hi there,';
  return '' +
    '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Action required: add your payout details</title></head>' +
    '<body style="margin:0;background:#f4f4f5;padding:24px 12px;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#18181b">' +
      // hidden preheader — controls the inbox preview snippet
      '<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;font-size:1px;line-height:1px">Payroll needs your bank / payout details so we can pay you on time &mdash; it takes about 2 minutes.</div>' +
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5"><tr><td align="center">' +
        '<table role="presentation" width="520" cellpadding="0" cellspacing="0" style="width:100%;max-width:520px;background:#ffffff;border:1px solid #e4e4e7;border-radius:14px;overflow:hidden;box-shadow:0 6px 24px rgba(220,38,38,0.10)">' +
          '<tr><td style="padding:18px 26px 12px"><img src="' + LOGO + '" alt="Simple" width="88" height="30" style="display:block;border:0;height:30px;width:88px"></td></tr>' +
          '<tr><td bgcolor="#0a0a0b" style="background:#0a0a0b;padding:22px 26px;border-bottom:4px solid #dc2626">' +
            '<span style="display:inline-block;background:#dc2626;color:#ffffff;font-size:11px;font-weight:bold;letter-spacing:1.5px;text-transform:uppercase;padding:5px 12px;border-radius:999px">&#9888;&#65039; Action required</span>' +
            '<div style="margin-top:14px;font-size:22px;line-height:1.3;color:#ffffff;font-weight:bold">Payroll can&rsquo;t pay you yet</div>' +
            '<div style="margin-top:6px;font-size:13px;color:#d4d4d8">We don&rsquo;t have your bank / payout details on file.</div>' +
          '</td></tr>' +
          '<tr><td style="padding:22px 26px 4px">' +
            '<p style="margin:0 0 14px;font-size:15px;color:#18181b">' + greeting + '</p>' +
            '<p style="margin:0 0 18px;font-size:14px;line-height:1.6;color:#3f3f46">So your salary reaches you on time, please add your bank / payout details. It only takes about 2 minutes, and your details are verified with a secure one-time code.</p>' +
            ctaButton() +
            '<p style="margin:10px 0 18px;font-size:12px;color:#71717a;word-break:break-all">Button not working? Copy and paste this link:<br><a href="' + UPDATE_LINK + '" style="color:#dc2626">' + esc(UPDATE_LINK) + '</a></p>' +
            // calm anti-phishing trust note (deliberately NOT red — reassurance, not alarm)
            '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f9fafb;border:1px solid #e4e4e7;border-radius:10px;margin:0 0 18px"><tr><td style="padding:13px 15px;font-size:12px;line-height:1.6;color:#52525b">&#128274; Simple will never ask for your password or a payment. Not sure this message is real? Email <a href="mailto:' + SUPPORT_EMAIL + '" style="color:#52525b;font-weight:bold">' + SUPPORT_EMAIL + '</a> before entering anything.</td></tr></table>' +
            '<p style="margin:0 0 4px;font-size:12px;line-height:1.6;color:#71717a">Already submitted your details? No action is needed &mdash; you can safely ignore this message.</p>' +
          '</td></tr>' +
          '<tr><td style="padding:16px 26px 20px;border-top:1px solid #f4f4f5"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="font-size:12px;color:#52525b;font-weight:bold">Simple &middot; Confidential</td><td align="right" style="font-size:11px;color:#71717a">Automated alert from Simple HRIS</td></tr></table></td></tr>' +
        '</table>' +
        '<div style="max-width:520px;margin:12px auto 0;font-size:11px;color:#71717a;text-align:center;line-height:1.5">You are receiving this because payroll needs your payout details in order to pay you.</div>' +
      '</td></tr></table>' +
    '</body></html>';
}

const SUBJECT = 'Action required: add your payout details so we can pay you';

const out = [];
for (const [email, name] of seen) {
  out.push({
    json: {
      to: email,
      name: name || '',
      subject: SUBJECT,
      html: renderHtml(name),
    },
  });
}
return out;
